// The Worker entry: OpenNext's Next.js handler, plus a cron that keeps the
// Jikan cache warm (see lib/jikan.ts) so the busy pages never wait on a cold
// MyAnimeList call.

// @ts-expect-error generated by `opennextjs-cloudflare build`
import { default as handler } from "./.open-next/worker.js";

export default {
  fetch: handler.fetch,
  async scheduled(_event: unknown, env: CloudflareEnv, ctx: { waitUntil(p: Promise<unknown>): void }) {
    ctx.waitUntil(handler.fetch(new Request("https://cupcake.internal/api/warm"), env, ctx));
  },
};
